package net.minecraft.server.level;
import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.world.level.*;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.phys.*;import cn.academy.port.solar.ImagFluxGenerator;import cn.academy.port.machine.ImagFluxReceiver;
public class ServerLevel {public final Map<BlockPos,BlockEntity> tiles=new LinkedHashMap<>();public final Map<BlockPos,ImagFluxGenerator> generators=new HashMap<>();public final Map<BlockPos,ImagFluxReceiver> receivers=new HashMap<>();public final Set<BlockPos> unloaded=new HashSet<>(),denied=new HashSet<>();public final Server server=new Server();public HitResult hit=new HitResult(HitResult.Type.MISS,null);public ClipContext lastClip;public int clips;public int lookups;public static class Server {public final java.util.List<ServerPlayer> players=new java.util.ArrayList<>();public Server getPlayerList(){return this;}public java.util.List<ServerPlayer> getPlayers(){return players;}public boolean sameThread=true;public boolean isSameThread(){return sameThread;}}public Server getServer(){return server;}public boolean hasChunkAt(BlockPos p){return !unloaded.contains(p);}public BlockEntity getBlockEntity(BlockPos p){lookups++;if(!hasChunkAt(p))throw new AssertionError("unloaded lookup");return tiles.get(p);}public boolean mayInteract(ServerPlayer player,BlockPos p){return !denied.contains(p);}public HitResult clip(ClipContext c){clips++;lastClip=c;return hit;}public <T> T getCapability(oracle.Capability<T> cap,BlockPos p,Object state,BlockEntity tile,Object ctx){return (T)(cap.name().equals("generator")?generators.get(p):receivers.get(p));}}
